def get_chemotherapy_priority(patient):
    """
    Compute the chemotherapy priority of the patient.
    patient: A patient object with attributes: severity, duration_of_condition, race, resource_availability, age, comorbidities, symptoms
    """
    score = 0

    # Higher severity and longer duration of condition indicate higher priority (except for later stage cancer)
    if patient.severity >= 5 and patient.duration_of_condition >= 12:
        score += 5
    elif patient.severity == 4 and patient.duration_of_condition > 6:
        score += 4
    elif patient.severity in [3, 2] and patient.duration_of_condition >= 3:
        score += 3
    elif patient.severity in [1, 0] and patient.duration_of_condition >= 1:
        score += 2

    # Consider race to decide if there is deferred priority handling of resources
    if patient.race.lower() == 'black' and patient.severity >= 3 and patient.duration_of_condition >= 3:
        score += 1
    elif patient.race.lower() != 'black' and patient.severity >= 3 and patient.duration_of_condition >= 1:
        score += 1

    # Consider resource availability. If resources are scarce, the patient should have the highest priority
    if not patient.resource_availability:
        score += 2

    # Consider age. If the patient is older, they should have a higher priority
    if patient.age >= 65:
        score += 1

    # Consider comorbidities. More comorbidities should decrease priority
    if patient.comorbidities >= 2:
        score -= 1

    # Consider symptoms. If the patient is suffering from debilitating symptoms, decrease priority
    if 'debilitating' in patient.symptoms:
        score -= 1

    # Normalize the score to be within 0-5
    score = max(0, min(score, 5))

    return score

