    severity_scores = {1:1, 2:2, 3:3, 4:2, 5:1, 6:1, 7:2, 8:3}
    score += severity_scores[patient.severity]

    # Symptomatic patients are more likely to require endoscopy
    symptoms_scores = {'stomach pain':2, 'heartburn':2, 'vomit':2, 'dizziness':1, 'chest pain':3}
    score += sum([ symptoms_scores.get(symptom, 0) for symptom in patient.symptoms if symptom in symptoms_scores])

    # Consider longer duration of condition and number of comorbidities
    if patient.duration_of_condition > 30 or patient.comorbidities >= 4:
        score += 3
    elif patient.duration_of_condition > 18 or patient.comorbidities >= 3:
        score += 2
    else:
        score += 1

    # Consider the patient's age
    age_scores = {a:i for i, a in enumerate(range(0,130,5), start=5)}
    score += age_scores[patient.age]

    # Consider the patient's race. If 'race' attribute is none or not a racial attribute, we default to the next lowest priority level
    race_scores = {'white':5, 'black':4, 'hispanic':3, 'asian':4, 'american indian':3, 'pacific islander':3, 'alaskan native':2, 'other':1}
    score += race_scores.get(patient.race, 0)

    # Consider resource availability and assign lower scores if not available
    if patient.resource_availability:
        score += 2
    else:
        score += 0

    return score

