def find_majority(nums):
    """
    :param nums: list of integers
    :return: the majority element, which occurs more than n/2 times in nums
    """
    counts = {}
    majority_threshold = len(nums) // 2

    for num in nums:
        if num not in counts:
            counts[num] = 1
        else:
            counts[num] += 1

        if counts[num] > majority_threshold:
            return num

    # In case no majority element exists
    return None

